<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['tenant_admin','manager','employee']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='tasks'; $pageTitle='Tasks';
if (is_post()) { verify_csrf(); $act=$_POST['action']??'';
  if($act==='delete') $pdo->prepare('DELETE FROM tasks WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]);
  elseif($act==='comment') { $tidTask=(int)$_POST['task_id']; $s=$pdo->prepare('SELECT id FROM tasks WHERE id=? AND tenant_id=?'); $s->execute([$tidTask,$tid]); if($s->fetch()) $pdo->prepare('INSERT INTO task_comments(tenant_id,task_id,user_id,body,created_at) VALUES(?,?,?,?,NOW())')->execute([$tid,$tidTask,$user['id'],trim($_POST['body']??'')]); flash('success','Comment added.'); redirect('tasks.php?comments='.$tidTask); }
  else { $pid=(int)($_POST['project_id']??0)?:null; if($pid){$s=$pdo->prepare('SELECT id FROM projects WHERE id=? AND tenant_id=?');$s->execute([$pid,$tid]); if(!$s->fetch()) $pid=null;}
    $labels=trim($_POST['labels']??'');
    $data=[trim($_POST['title']??''),$_POST['description']??null,$pid,(int)($_POST['assigned_to']??0)?:null,$_POST['priority']??'medium',$_POST['status']??'todo',$_POST['due_date']?:null,$labels?:null,(int)($_POST['depends_on']??0)?:null,!empty($_POST['is_recurring'])?1:0];
    if(!empty($_POST['id'])) $pdo->prepare('UPDATE tasks SET title=?,description=?,project_id=?,assigned_to=?,priority=?,status=?,due_date=?,labels=?,depends_on=?,is_recurring=? WHERE id=? AND tenant_id=?')->execute([...$data,(int)$_POST['id'],$tid]);
    else $pdo->prepare('INSERT INTO tasks(tenant_id,title,description,project_id,assigned_to,priority,status,due_date,labels,depends_on,is_recurring,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([$tid,...$data,$user['id']]);
    // keep labels table in sync (first label as primary row)
    if($labels){ foreach(array_filter(array_map('trim',explode(',',$labels))) as $lb){ $pdo->prepare('INSERT IGNORE INTO task_labels(tenant_id,name) VALUES(?,?)')->execute([$tid,$lb]); } }
    flash('success','Task saved.'); }
  redirect('tasks.php'.(!empty($_GET['project_id'])?'?project_id='.(int)$_GET['project_id']:'')); }
$projFilter=(int)($_GET['project_id']??0);
$sql='SELECT t.*,u.name assignee,p.name project_name FROM tasks t LEFT JOIN users u ON u.id=t.assigned_to LEFT JOIN projects p ON p.id=t.project_id WHERE t.tenant_id=?'; $args=[$tid]; if($projFilter){$sql.=' AND t.project_id=?';$args[]=$projFilter;} $sql.=' ORDER BY t.due_date IS NULL,t.due_date,t.id DESC';
$s=$pdo->prepare($sql); $s->execute($args); $rows=$s->fetchAll();
$s=$pdo->prepare('SELECT id,name FROM users WHERE tenant_id=? ORDER BY name'); $s->execute([$tid]); $users=$s->fetchAll();
$s=$pdo->prepare('SELECT id,name FROM projects WHERE tenant_id=? AND status!="archived" ORDER BY name'); $s->execute([$tid]); $projects=$s->fetchAll();
$edit=null; if(!empty($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM tasks WHERE id=? AND tenant_id=?');$s->execute([(int)$_GET['edit'],$tid]);$edit=$s->fetch();}
$comments=[]; $commentTask=null; if(!empty($_GET['comments'])){ $commentTask=(int)$_GET['comments']; $s=$pdo->prepare('SELECT c.*,u.name author FROM task_comments c LEFT JOIN users u ON u.id=c.user_id WHERE c.task_id=? AND c.tenant_id=? ORDER BY c.id'); $s->execute([$commentTask,$tid]); $comments=$s->fetchAll(); }
include __DIR__ . '/includes/header.php'; ?>
<div class="card p-3 mb-3"><form class="row g-2" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>">
<div class="col-md-3"><input class="form-control" name="title" placeholder="Task title" required value="<?= e($edit['title']??'') ?>"></div>
<div class="col-md-2"><select class="form-select" name="project_id"><option value="">Project…</option><?php foreach($projects as $p): ?><option value="<?= $p['id'] ?>" <?= ($edit['project_id']??$projFilter)==$p['id']?'selected':'' ?>><?= e($p['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><select class="form-select" name="assigned_to"><option value="">Assign…</option><?php foreach($users as $u): ?><option value="<?= $u['id'] ?>" <?= ($edit['assigned_to']??'')==$u['id']?'selected':'' ?>><?= e($u['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-1"><select class="form-select" name="priority"><?php foreach(['low','medium','high','urgent'] as $c): ?><option <?= ($edit['priority']??'medium')===$c?'selected':'' ?>><?= $c ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><select class="form-select" name="status"><?php foreach(['todo'=>'To Do','in_progress'=>'In Progress','review'=>'Review','done'=>'Done'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($edit['status']??'todo')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></div>
<div class="col-md-2"><input class="form-control" type="date" name="due_date" value="<?= e($edit['due_date']??'') ?>"></div>
<div class="col-md-3"><input class="form-control" name="labels" placeholder="Labels, comma-separated" value="<?= e($edit['labels']??'') ?>"></div>
<div class="col-md-2"><select class="form-select" name="depends_on"><option value="">Depends on…</option><?php foreach($rows as $r): if(($edit['id']??0)!=$r['id']): ?><option value="<?= $r['id'] ?>" <?= ($edit['depends_on']??'')==$r['id']?'selected':'' ?>><?= e($r['title']) ?></option><?php endif; endforeach; ?></select></div>
<div class="col-md-3"><input class="form-control" name="description" placeholder="Description" value="<?= e($edit['description']??'') ?>"></div>
<div class="col-md-1 form-check pt-2"><input class="form-check-input" type="checkbox" name="is_recurring" id="rec" <?= !empty($edit['is_recurring'])?'checked':'' ?>><label for="rec">Recurring</label></div>
<div class="col-md-2"><button class="btn btn-primary w-100"><?= $edit?'Update':'Add' ?> task</button></div></form>
<p class="small text-muted mt-2 mb-0">Tip: use the <a href="board.php">Kanban Board</a> to drag tasks between To Do / In Progress / Review / Done.</p></div>
<?php if($commentTask): ?><div class="card p-3 mb-3"><h6>Comments for task #<?= $commentTask ?></h6><?php foreach($comments as $c): ?><div class="border-bottom py-2 small"><strong><?= e($c['author']??'') ?></strong> · <?= e($c['created_at']) ?><br><?= e($c['body']) ?></div><?php endforeach; if(!$comments) echo '<p class="text-muted small">No comments yet.</p>'; ?>
<form method="post" class="d-flex gap-2 mt-2"><?= csrf_field() ?><input type="hidden" name="action" value="comment"><input type="hidden" name="task_id" value="<?= $commentTask ?>"><input class="form-control" name="body" placeholder="Add a comment…" required><button class="btn btn-primary">Post</button></form></div><?php endif; ?>
<div class="card p-0 overflow-auto"><table class="table table-hover mb-0"><thead><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Priority</th><th>Status</th><th>Labels</th><th>Due</th><th></th></tr></thead><tbody>
<?php foreach($rows as $r): $over=$r['status']!=='done'&&$r['due_date']&&$r['due_date']<date('Y-m-d'); ?><tr class="<?= $r['status']==='done'?'text-muted':'' ?>"><td><?= e($r['title']) ?><?php if($r['depends_on']): ?> <span class="badge bg-light text-dark">after #<?= (int)$r['depends_on'] ?></span><?php endif; ?></td><td><?= e($r['project_name']??'—') ?></td><td><?= e($r['assignee']??'—') ?></td><td><span class="badge bg-<?= $r['priority']==='urgent'?'danger':($r['priority']==='high'?'warning':'secondary') ?>"><?= e($r['priority']) ?></span></td><td><?= e($r['status']) ?></td><td><?= e($r['labels']??'') ?></td><td class="<?= $over?'text-danger fw-bold':'' ?>"><?= e($r['due_date']??'') ?></td>
<td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="?comments=<?= $r['id'] ?>">Comments</a> <a class="btn btn-sm btn-outline-primary" href="?edit=<?= $r['id'] ?>">Edit</a> <form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Delete task?">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php include __DIR__ . '/includes/footer.php'; ?>
